import unittest
from text_window import *
import sqlite3


class BoundCursor(sqlite3.Cursor):
    def execute(self, sql, parameters=()):
        if self.connection.require_binding:
            assert parameters, 'bind the business arguments instead of formatting SQL'
            self.connection.bound_calls += 1
        return super().execute(sql, parameters)

class BoundConnection(sqlite3.Connection):
    require_binding = False
    bound_calls = 0

    def execute(self, sql, parameters=()):
        if self.require_binding:
            assert parameters, 'bind the business arguments instead of formatting SQL'
            self.bound_calls += 1
        return super().execute(sql, parameters)

    def cursor(self, factory=BoundCursor):
        return super().cursor(factory)


class TextWindow(unittest.TestCase):
    def test_index_length_and_storage_kind(self):
        rows=[('shipment',1,4,'ship'),('shipment',-4,2,'me'),('shipment',5,-3,'hip'),('shipment',-1,-2,'en'),('shipment',3,None,'ipment'),('shipment',-3,None,'ent'),('木🙂oak',2,2,'🙂o'),('木🙂oak',4,-2,'🙂o'),('oak',99,2,''),('oak',1,0,''),(b'\x10\x20\x30\x40',-2,1,b'\x30'),(b'\x10\x20\x30\x40',3,-2,b'\x10\x20')]
        with sqlite3.connect(':memory:') as conn:
            for value,start,length,expected in rows:
                with self.subTest(value=value,start=start,length=length):
                    actual=window(conn,value,start,length)
                    self.assertEqual(actual,expected)
                    self.assertIs(type(actual),type(expected))

    def test_bound_sql_and_caller_connection(self):
        conn = sqlite3.connect(':memory:', factory=BoundConnection)
        conn.execute('CREATE TABLE dispatch(label TEXT)')
        conn.execute("INSERT INTO dispatch VALUES ('keep this row')")
        conn.commit()
        changes = conn.total_changes
        conn.require_binding = True
        try:
            self.assertEqual(window(conn, "cargo'松🙂", -3, 2), "'松")
            self.assertGreater(conn.bound_calls, 0, 'execute SQL on the supplied connection')
        finally:
            conn.require_binding = False
        self.assertEqual(conn.total_changes, changes)
        self.assertEqual(conn.execute('SELECT label FROM dispatch').fetchall(), [('keep this row',)])
        conn.close()


if __name__ == '__main__':
    unittest.main()

